/* Amber Minimal Theme — Tailwind v3 (rgb) */
/* Channel triplets — consume via rgb(var(--token)). See tailwind.config snippet in docs. */

@layer base {
  /* Amber Minimal Theme - Auto-generated from tweakcn */

  /* Light mode (:root) */
  :root {
    --background: 255 255 255;
    --foreground: 38 38 38;
    --card: 255 255 255;
    --card-foreground: 38 38 38;
    --popover: 255 255 255;
    --popover-foreground: 38 38 38;
    --primary: 244 159 30;
    --primary-foreground: 0 0 0;
    --secondary: 245 245 245;
    --secondary-foreground: 75 86 102;
    --muted: 248 248 248;
    --muted-foreground: 108 114 126;
    --accent: 255 252 240;
    --accent-foreground: 143 65 19;
    --destructive: 241 68 68;
    --destructive-foreground: 255 255 255;
    --border: 228 232 239;
    --input: 228 232 239;
    --ring: 244 159 30;
    --chart-1: 244 159 30;
    --chart-2: 219 120 0;
    --chart-3: 183 83 1;
    --chart-4: 143 65 19;
    --chart-5: 121 50 7;
    --radius: 0.375rem;
    --sidebar: 248 248 248;
    --sidebar-foreground: 38 38 38;
    --sidebar-primary: 244 159 30;
    --sidebar-primary-foreground: 255 255 255;
    --sidebar-accent: 255 252 240;
    --sidebar-accent-foreground: 143 65 19;
    --sidebar-border: 228 232 239;
    --sidebar-ring: 244 159 30;
    --font-sans: Inter, sans-serif;
    --font-serif: Source Serif 4, serif;
    --font-mono: JetBrains Mono, monospace;
    --shadow-color: 0 0 0;
    --shadow-opacity: 0.1;
    --shadow-blur: 8px;
    --shadow-spread: -1px;
    --shadow-offset-x: 0px;
    --shadow-offset-y: 4px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0px 4px 8px -1px hsl(0 0% 0% / 0.05);
    --shadow-xs: 0px 4px 8px -1px hsl(0 0% 0% / 0.05);
    --shadow-sm:
      0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 1px 2px -2px hsl(0 0% 0% / 0.1);
    --shadow:
      0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 1px 2px -2px hsl(0 0% 0% / 0.1);
    --shadow-md:
      0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 2px 4px -2px hsl(0 0% 0% / 0.1);
    --shadow-lg:
      0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 4px 6px -2px hsl(0 0% 0% / 0.1);
    --shadow-xl:
      0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 8px 10px -2px hsl(0 0% 0% / 0.1);
    --shadow-2xl: 0px 4px 8px -1px hsl(0 0% 0% / 0.25);
    --tracking-normal: 0em;
  }

  /* Dark mode (.dark) */
  .dark {
    --background: 22 22 22;
    --foreground: 228 228 228;
    --card: 38 38 38;
    --card-foreground: 228 228 228;
    --popover: 38 38 38;
    --popover-foreground: 228 228 228;
    --primary: 244 159 30;
    --primary-foreground: 0 0 0;
    --secondary: 38 38 38;
    --secondary-foreground: 228 228 228;
    --muted: 38 38 38;
    --muted-foreground: 164 164 164;
    --accent: 143 65 19;
    --accent-foreground: 253 228 132;
    --destructive: 241 68 68;
    --destructive-foreground: 255 255 255;
    --border: 64 64 64;
    --input: 64 64 64;
    --ring: 244 159 30;
    --chart-1: 251 192 49;
    --chart-2: 219 120 0;
    --chart-3: 143 65 19;
    --chart-4: 183 83 1;
    --chart-5: 143 65 19;
    --radius: 0.375rem;
    --sidebar: 15 15 15;
    --sidebar-foreground: 228 228 228;
    --sidebar-primary: 244 159 30;
    --sidebar-primary-foreground: 255 255 255;
    --sidebar-accent: 143 65 19;
    --sidebar-accent-foreground: 253 228 132;
    --sidebar-border: 64 64 64;
    --sidebar-ring: 244 159 30;
    --font-sans: Inter, sans-serif;
    --font-serif: Source Serif 4, serif;
    --font-mono: JetBrains Mono, monospace;
    --shadow-color: 0 0 0;
    --shadow-opacity: 0.1;
    --shadow-blur: 8px;
    --shadow-spread: -1px;
    --shadow-offset-x: 0px;
    --shadow-offset-y: 4px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0px 4px 8px -1px hsl(0 0% 0% / 0.05);
    --shadow-xs: 0px 4px 8px -1px hsl(0 0% 0% / 0.05);
    --shadow-sm:
      0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 1px 2px -2px hsl(0 0% 0% / 0.1);
    --shadow:
      0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 1px 2px -2px hsl(0 0% 0% / 0.1);
    --shadow-md:
      0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 2px 4px -2px hsl(0 0% 0% / 0.1);
    --shadow-lg:
      0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 4px 6px -2px hsl(0 0% 0% / 0.1);
    --shadow-xl:
      0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 8px 10px -2px hsl(0 0% 0% / 0.1);
    --shadow-2xl: 0px 4px 8px -1px hsl(0 0% 0% / 0.25);
  }

}
